using System;
using System.Collections.Generic;
using System.IO;
using System.Drawing;
using System.Windows.Forms;

public sealed class SlotCardState {
 public int Slot;public int? Id,Inputs,Outputs;public bool Complete{get{return Id.HasValue&&Inputs.HasValue&&Outputs.HasValue;}}
 public string Signature{get{return Slot+":"+Id+":"+Inputs+":"+Outputs;}}
 public string Detected{get{return !Complete?"Reading card…":Id==255&&Inputs==0&&Outputs==0?"No card reported":"ID "+Id.Value.ToString("X2")+" · "+Inputs+" in / "+Outputs+" out";}}
 public string Model{get{return CardLabels.Get(Signature);}}
 public string SourceDetail{get{return Model??(!Complete?"Card reading…":"ID "+Id.Value.ToString("X2")+" · "+Inputs+"/"+Outputs+" I/O");}}
}
public static class CardLabels {
 static Dictionary<string,string> labels;static string FilePath{get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"confirmed-card-models.tsv");}}
 static void Load(){if(labels!=null)return;labels=new Dictionary<string,string>();if(!File.Exists(FilePath))return;foreach(string line in File.ReadAllLines(FilePath)){string[] cells=line.Split('\t');if(cells.Length==2)labels[cells[0]]=cells[1];}}
 public static string Get(string signature){Load();string value;return labels.TryGetValue(signature,out value)?value:null;}
 public static void Save(Dictionary<string,string> values){Load();var next=new Dictionary<string,string>(labels);foreach(var p in values){string text=p.Value.Trim();if(text.Length>60||text.IndexOfAny(new char[]{'\r','\n','\t'})>=0)throw new ArgumentException("Use a model label of up to 60 characters.");if(text.Length==0)next.Remove(p.Key);else next[p.Key]=text;}var lines=new List<string>();foreach(var p in next)lines.Add(p.Key+"\t"+p.Value);File.WriteAllLines(FilePath,lines.ToArray());labels=next;}
 public static void Test(){var known=new SlotCardState{Slot=0,Id=4,Inputs=8,Outputs=0};if(!known.Complete||known.Detected!="ID 04 · 8 in / 0 out")throw new Exception("Card identity formatting failed");if(new SlotCardState{Slot=0,Id=5,Inputs=8,Outputs=8}.Signature==known.Signature)throw new Exception("Different cards share a label key");if(new SlotCardState{Slot=1,Id=4,Inputs=8,Outputs=0}.Signature==known.Signature)throw new Exception("Different slots share a label key");}
}
public sealed partial class FaderConnection {
 
 public SlotCardState Card(int slot){lock(gate)return new SlotCardState{Slot=slot,Id=ScalarValue(MixerParameter.CardInfo(slot,0),double.PositiveInfinity),Inputs=ScalarValue(MixerParameter.CardInfo(slot,1),double.PositiveInfinity),Outputs=ScalarValue(MixerParameter.CardInfo(slot,2),double.PositiveInfinity)};}

}
sealed partial class Studio {
 static void TestSourceDisplayStable(){using(var app=new Studio())using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"source-display-test.txt"))){app.Show();app.banks.SelectedIndex=1;app.Connect();var until=DateTime.UtcNow.AddSeconds(3);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}app.channel=25;app.Details();string original=app.sourceValue.Text;if(!original.Contains("Slot"))throw new Exception("Slot source did not load");int changes=0;app.sourceValue.TextChanged+=delegate{changes++;};for(int i=0;i<250;i++)app.Details();until=DateTime.UtcNow.AddSeconds(2);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}if(changes!=0)throw new Exception("Static source rewritten "+changes+" times");log.WriteLine("PASS: zero Source text changes during 250 inspector refreshes and two seconds of live updates.");app.channel=26;app.Details();if(changes!=1)throw new Exception("Selecting another source did not update exactly once");log.WriteLine("PASS: channel selection updates the complete source label once.");app.Close();}}
 static void TestInspectorCard(){using(var app=new Studio())using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"inspector-card-test.txt"))){app.Show();app.banks.SelectedIndex=1;app.Connect();var end=DateTime.UtcNow.AddSeconds(3);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(10);}app.channel=25;app.Details();if(!app.cardField.Visible||!app.cardSave.Enabled||app.editingCardSlot<0)throw new Exception("Inspector card editor not available");var card=app.midi.Card(app.editingCardSlot);string original=card.Model;log.WriteLine("Detected slot "+(card.Slot+1)+": "+card.Detected);try{app.cardModel.Text="Temporary label test";app.cardSave.PerformClick();if(CardLabels.Get(card.Signature)!="Temporary label test")throw new Exception("Inspector card label did not save");app.Details();if(!app.sourceValue.Text.Contains("Temporary label test"))throw new Exception("Source detail did not show card label");log.WriteLine("PASS: editable inspector label saved and source detail updated.");}finally{CardLabels.Save(new Dictionary<string,string>{{card.Signature,original??""}});}app.channel=1;app.Details();if(app.cardField.Visible)throw new Exception("Card editor shown for onboard source");log.WriteLine("PASS: card editor hidden for onboard sources; original labels restored.");app.Close();}}
 Panel cardField=new Panel();Label cardHeading=new Label(),cardDetected=new Label();TextBox cardModel=new TextBox();Button cardSave=new Button();int editingCardSlot=-1;string editingCardSignature;bool cardLabelDirty;
 void InstallInspectorCard(){cardField.Width=228;cardField.Height=88;cardField.Margin=new Padding(0,0,12,5);cardField.Visible=false;cardHeading.Dock=DockStyle.Top;cardHeading.Height=20;cardDetected.Dock=DockStyle.Top;cardDetected.Height=20;cardDetected.ForeColor=Color.FromArgb(160,177,193);cardModel.Dock=DockStyle.Top;cardModel.MaxLength=60;cardModel.BackColor=Color.FromArgb(38,47,58);cardModel.ForeColor=ForeColor;cardSave.Text="Save card label";cardSave.Dock=DockStyle.Bottom;Style(cardSave);cardField.Controls.Add(cardModel);cardField.Controls.Add(cardDetected);cardField.Controls.Add(cardHeading);cardField.Controls.Add(cardSave);info.Controls.Add(cardField);info.Controls.SetChildIndex(cardField,2);cardModel.TextChanged+=delegate{if(cardModel.Focused)cardLabelDirty=true;};cardSave.Click+=delegate{try{if(midi==null||editingCardSlot<0)throw new InvalidOperationException("Select an input patched to a slot first.");var card=midi.Card(editingCardSlot);var input=midi.Channel(SelectedId);if(!card.Complete||card.Signature!=editingCardSignature||input.Source<25||input.Source>120||(input.Source.Value-25)/16!=editingCardSlot)throw new InvalidOperationException("The input source changed. Select the channel again before saving.");CardLabels.Save(new Dictionary<string,string>{{card.Signature,cardModel.Text}});cardLabelDirty=false;state.Text="Saved label for slot "+(editingCardSlot+1);}catch(Exception e){state.Text=e.Message;}};}
 void RefreshInspectorCard(MixerChannelState input){if(midi==null||SelectedId>=96||!input.Source.HasValue||input.Source<25||input.Source>120){cardField.Visible=false;editingCardSlot=-1;editingCardSignature=null;cardLabelDirty=false;return;}int slot=(input.Source.Value-25)/16;var card=midi.Card(slot);cardField.Visible=true;cardHeading.Text="Slot "+(slot+1)+" · Card label";cardDetected.Text=card.Detected;if(editingCardSignature!=card.Signature){editingCardSignature=card.Signature;editingCardSlot=slot;cardLabelDirty=false;cardModel.Text=card.Model??"";}else if(!cardLabelDirty&&cardModel.Text!=(card.Model??""))cardModel.Text=card.Model??"";cardModel.Enabled=cardSave.Enabled=card.Complete;}
 void InstallCardUi(){var button=new Button{Text="Slot cards…",AutoSize=true};Style(button);toolbar.Controls.Add(button);button.Click+=delegate{if(midi==null){state.Text="Connect to read the installed cards.";return;}ShowCards();};}
 void ShowCards(){using(var window=new Form{Text="DM2000 · Slot cards",Size=new Size(790,380),MinimumSize=new Size(650,330),StartPosition=FormStartPosition.CenterParent,BackColor=BackColor,ForeColor=ForeColor,Font=Font}){var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,Padding=new Padding(14)};root.RowStyles.Add(new RowStyle(SizeType.Absolute,52));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,40));window.Controls.Add(root);root.Controls.Add(new Label{Text="Startup IDs and channel counts from the desk. Model labels are editable and saved locally.\r\nEach label stays tied to its slot, reported card ID and I/O count.",Dock=DockStyle.Fill},0,0);var grid=new DataGridView{Dock=DockStyle.Fill,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,BackgroundColor=Color.FromArgb(32,38,46)};grid.DefaultCellStyle.BackColor=Color.FromArgb(32,38,46);grid.DefaultCellStyle.ForeColor=ForeColor;grid.Columns.Add("slot","Slot");grid.Columns.Add("id","Reported ID");grid.Columns.Add("input","Inputs");grid.Columns.Add("output","Outputs");grid.Columns.Add("model","Model label");grid.Columns[0].FillWeight=40;grid.Columns[1].FillWeight=70;grid.Columns[2].FillWeight=45;grid.Columns[3].FillWeight=45;grid.Columns[4].FillWeight=200;for(int c=0;c<4;c++)grid.Columns[c].ReadOnly=true;string[] signatures=new string[6];for(int slot=0;slot<6;slot++){var card=midi.Card(slot);signatures[slot]=card.Signature;grid.Rows.Add(slot+1,card.Id.HasValue?"0x"+card.Id.Value.ToString("X2"):"Reading…",card.Inputs,card.Outputs,card.Model??"");grid.Rows[slot].Cells[4].ReadOnly=!card.Complete||(card.Id==255&&card.Inputs==0&&card.Outputs==0);}root.Controls.Add(grid,0,1);var save=new Button{Text="Save labels",AutoSize=true,Dock=DockStyle.Right};Style(save);root.Controls.Add(save,0,2);save.Click+=delegate{try{grid.EndEdit();var values=new Dictionary<string,string>();for(int slot=0;slot<6;slot++){var card=midi==null?null:midi.Card(slot);if(card==null||!card.Complete||card.Signature!=signatures[slot])throw new InvalidOperationException("Card information changed. Close and reopen this view before saving.");values[card.Signature]=Convert.ToString(grid.Rows[slot].Cells[4].Value);}CardLabels.Save(values);window.Close();}catch(Exception e){MessageBox.Show(window,e.Message,"Slot cards",MessageBoxButtons.OK,MessageBoxIcon.Information);}};window.ShowDialog(this);}}
}



